// Shape tests for this pack's scheduled-task declarations.
//
// The Claudinite scheduler reads frequency / agent_model / expected_outcome from
// task.mjs — never from anywhere else — so a typo'd enum or a missing field means
// a task silently never fires. The canon's own `task-declaration-shape` check
// asserts that statically at author time; this asserts it by IMPORTING each
// declaration, which additionally parse-checks the module and its worker wiring.
// The contract's legal values are restated here as literals rather than imported
// from the mount, so this file never couples to the vendored canon.

import { test } from "node:test";
import assert from "node:assert/strict";
import { existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";

import refreshShows from "./refresh-shows/task.mjs";
import refreshTickets from "./refresh-tickets/task.mjs";
import { terms as ticketTerms } from "./refresh-tickets/preconditions.mjs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));

const FREQUENCIES = ["daily", "weekly", "monthly", "manual"];
const MODELS = ["opus", "sonnet", "haiku", "none"];
const OUTCOMES = ["none", "open-pr", "merged-pr"];

// Both scraping tasks are OFF, and `manual` is what carries that: a manual task
// has no occurrence for the scheduler to instantiate. Pinned here so turning one
// back on is a deliberate edit to this file rather than a token nobody re-reads.
// The declarative precondition is the ONLY gate mechanism — the `precondition`
// function form and its `precondition_signals` companion are retired
// (missingbulb/Claudinite#1617), so both are asserted ABSENT rather than present.
const DECLARED = [
  ["refresh-shows", refreshShows, "manual", ["none"], {}],
  ["refresh-tickets", refreshTickets, "manual", ["in-festival"], ticketTerms],
];

for (const [dir, decl, frequency, preconditions, terms] of DECLARED) {
  test(`${dir} declares the full task contract`, () => {
    assert.equal(decl.id, dir, "the id must match the task's directory name");
    assert.equal(decl.frequency, frequency);
    assert.ok(FREQUENCIES.includes(decl.frequency), `illegal frequency ${decl.frequency}`);
    assert.ok(MODELS.includes(decl.agent_model), `illegal agent_model ${decl.agent_model}`);
    assert.ok(OUTCOMES.includes(decl.expected_outcome), `illegal expected_outcome ${decl.expected_outcome}`);
    assert.deepEqual(decl.preconditions, preconditions);
    assert.equal(typeof decl.agent_instructions, "string");
    // The retired form, asserted gone: a declaration carrying both is a contract
    // violation, and one carrying only the function stops running the moment the
    // mount drops support for it.
    assert.equal(decl.precondition, undefined);
    assert.equal(decl.precondition_signals, undefined);
    // Every named condition resolves — a built-in, or one this task's own
    // preconditions.mjs exports. An unknown term is a run failure, not a decline.
    for (const name of decl.preconditions) {
      assert.ok(name === "none" || name in terms, `${dir} names the unresolvable condition "${name}"`);
    }
  });

  test(`${dir} is agentless and its worker exists`, () => {
    // Both of these tasks are deterministic ports of retired workflows: no agent,
    // so the contract requires the work to be a bounded code-work subprocess.
    assert.equal(decl.agent_model, "none");
    assert.equal(decl.code_work, "bash worker.sh");
    assert.ok(Number.isInteger(decl.code_work_timeout) && decl.code_work_timeout > 0);
    assert.ok(existsSync(path.join(__dirname, dir, "worker.sh")), "the declared worker must exist beside task.mjs");
  });

  test(`${dir}'s own terms each return a verdict with a reason`, () => {
    for (const [name, term] of Object.entries(terms)) {
      const verdict = term.holds({}, { now: new Date("2026-08-15T11:49:00Z") });
      assert.equal(typeof verdict.holds, "boolean", `${name} answered no verdict`);
      assert.ok(verdict.reason.length > 0, "every verdict explains itself — it lands in the scheduler's job summary");
    }
  });
}

// `none` IS "run whenever it is pulled": the empty precondition, whose trigger is
// the calendar or the work item somebody filed.
test("refresh-shows states no condition, so a pulled run always proceeds", () => {
  assert.deepEqual(refreshShows.preconditions, ["none"]);
});

// The clock reaches the term from the ENGINE rather than the process, which is
// what makes the festival gate assertable at a chosen instant at all.
test("the in-festival term answers about the instant it is handed", () => {
  const at = (iso) => ticketTerms["in-festival"].holds({}, { now: new Date(iso) });
  assert.equal(at("2026-08-15T11:49:00Z").holds, true);
  assert.equal(at("2026-07-31T22:49:00Z").holds, false); // 23:49 BST on 31 July
  assert.equal(at("2026-07-31T23:49:00Z").holds, true);  // 00:49 BST on 1 August
  assert.ok(at("2026-09-15T11:49:00Z").reason.includes("outside the festival"));
});

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/missingbulb/Claudinite/blob/main/packs/claudinite-tasks/task.schema.json",
  "title": "Claudinite task declaration",
  "description": "A tasks/<name>/task.json: what a scheduled task is, when it runs, and what it may write. The runtime contract is packs/claudinite-tasks/task-contract.mjs; the enums here mirror its lists and a test holds them in step. Absent, preconditions is run-always, automerge is nothing and agent_model is none; the timeouts have no default.",
  "type": "object",
  "required": [
    "id",
    "description",
    "frequency",
    "expected_outcome"
  ],
  "additionalProperties": false,
  "properties": {
    "$schema": {
      "type": "string"
    },
    "id": {
      "type": "string",
      "minLength": 1,
      "description": "The task's name — the same as its directory name."
    },
    "description": {
      "type": "string",
      "minLength": 1,
      "description": "What the task does, or why it exists, in at most fifty words — never what the other fields already say (the cadence, the conditions, the policy, the files)."
    },
    "frequency": {
      "type": "string",
      "enum": [
        "daily",
        "weekly",
        "monthly",
        "manual"
      ],
      "description": "The anchor the task is instantiated on. `manual` is woken by whatever knows the event happened."
    },
    "preconditions": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "The conditions that must all hold for the task to run: built-in terms (e.g. \"substantive-change\", \"commits-under:<dir>\"), terms the task's own preconditions.mjs exports, `||` between alternatives. Optional: absent, the task runs always ([\"none\"])."
    },
    "expected_outcome": {
      "type": "string",
      "enum": [
        "none",
        "pr"
      ],
      "description": "The write ceiling: `none` may never open a pull request, `pr` may open one."
    },
    "automerge": {
      "description": "What may land unreviewed beside `expected_outcome: pr`: \"nothing\", \"anything\", or a list of diff classes, each optionally reject:-prefixed and narrowable with `&&`. Optional: defaults to \"nothing\".",
      "oneOf": [
        {
          "type": "string",
          "enum": [
            "nothing",
            "anything"
          ]
        },
        {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      ]
    },
    "agent_model": {
      "type": "string",
      "enum": [
        "opus",
        "sonnet",
        "haiku",
        "none"
      ],
      "description": "The model family the agentic phase runs at; `none` runs no agent. Optional: defaults to `none`."
    },
    "agent_instructions": {
      "type": "string",
      "minLength": 1,
      "description": "The worker spec the agent session reads, a file beside this declaration (conventionally task.md). Required beside an agent_model other than none; no default."
    },
    "agent_execution_timeout": {
      "type": "integer",
      "minimum": 1,
      "description": "Seconds bounding the agentic run — generous; extreme protection, not a scheduling knob. Required beside an agent_model other than none: a running agent always has a bound."
    },
    "code_work": {
      "type": "string",
      "minLength": 1,
      "description": "The deterministic first phase: a command run with the task directory as cwd, e.g. \"node worker.mjs\". Task-local — no absolute path, no `..`. Optional: absent, there is no code work."
    },
    "code_work_timeout": {
      "type": "integer",
      "minimum": 1,
      "description": "Seconds after which the code_work subprocess is killed and the task fails. Required beside code_work: a subprocess always has a bound."
    },
    "schedule_after": {
      "type": "array",
      "items": {
        "type": "string",
        "pattern": "^[^/\\s]+/[^/\\s]+$"
      },
      "description": "Task ids (\"<pack>/<task>\") this task yields to while their items are live this cycle."
    },
    "on_interrupt": {
      "type": "string",
      "enum": [
        "requeue",
        "needs-human"
      ],
      "description": "What happens to the work item when a recovery path would re-execute it. Default `requeue`; `needs-human` for a genuinely one-shot side effect."
    },
    "invocation_endpoint": {
      "type": "string",
      "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$",
      "description": "A key in the repo's taskScheduler.agenticTaskInvocationEndpoints — never a URL — for a task needing reach an ordinary session in its repo does not have."
    },
    "code_work_required_secrets": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "The repo Actions secret names the code-work phase needs configured — the phase that runs Action-side, where a secret exists. Never GITHUB_* or CLAUDINITE_*."
    },
    "required_secrets": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "deprecated": true,
      "description": "The retired spelling of code_work_required_secrets; normalized at the door. Rename it."
    },
    "model_from_request": {
      "const": true,
      "description": "Reserved to the engine's built-in request task: run at the model the work item names."
    },
    "session_scope": {
      "type": "string",
      "enum": [
        "self",
        "fleet"
      ],
      "deprecated": true,
      "description": "Read by nothing since #974. Drop it; name an invocation_endpoint if the task needs wider reach."
    }
  }
}

