// Where a task's declaration lives and how it is loaded — the one place that
// knows a task folder may spell its declaration two ways (task-declaration-text.mjs
// says which two and why). Everything that resolves a declaration — discovery, the
// dispatch validators, the checks that gate on a task folder — goes through the
// names here, so the retirement of the module form is one edit in one file.

import { existsSync, readFileSync } from 'node:fs';
import { basename, dirname, join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { TASK_DECLARATION_FILE, LEGACY_TASK_DECLARATION_FILE, TASK_DECLARATION_FILES, parseTaskDeclaration } from './task-declaration-text.mjs';

export * from './task-declaration-text.mjs';

// The declaration file a task directory carries, or null when it carries none.
// Both present is not "prefer one": it is two declarations for one task, and the
// caller reports it rather than guessing which the author meant.
export function findTaskDeclaration(taskDir) {
  const present = TASK_DECLARATION_FILES.filter((name) => existsSync(join(taskDir, name)));
  if (present.length === 0) return null;
  if (present.length > 1) {
    throw new Error(`${taskDir} carries both ${present.join(' and ')} — delete ${LEGACY_TASK_DECLARATION_FILE}, ${TASK_DECLARATION_FILE} is the declaration`);
  }
  return join(taskDir, present[0]);
}

// The declaration's raw object, before normalization. A JSON file that does not
// parse, or a module that does not import, throws with the file's own message —
// the callers turn that into a per-task error, never a sunk scan.
export async function loadTaskDeclaration(file) {
  if (basename(file) === TASK_DECLARATION_FILE) return parseTaskDeclaration(readFileSync(file, 'utf8'));
  return (await import(pathToFileURL(file).href)).default;
}

// The declaration file a `.../tasks/<name>/task.md` path's folder carries, given
// only an `exists` capability over repo-relative paths (the dispatch validator's
// world). Same rule as `findTaskDeclaration`; a folder with both returns null with
// `both: true` so the caller can say so.
export function siblingTaskDeclaration(taskMdPath, exists) {
  const dir = dirname(taskMdPath);
  const present = TASK_DECLARATION_FILES.map((name) => `${dir}/${name}`).filter((p) => exists(p));
  if (present.length === 1) return { file: present[0], both: false };
  return { file: null, both: present.length > 1 };
}

content.content:
1	// The task declaration contract (per-project-scheduling DESIGN §1) — the single
2	// source of truth for what a `tasks/<name>/task.json` must carry.
3	// Both the author-time `task-declaration-shape` check and the executor-side
4	// `validate-dispatch` validate against this one function, so the accepted shape
5	// can never drift between the two surfaces.
6	
7	import { ACCEPTED_FREQUENCIES, normalizeFrequency } from './calendar.mjs';
8	import { MODEL_FAMILIES } from './model-map.mjs';
9	import { EXECUTING_LEASH_MS } from './queue/leases.mjs';
10	import { normalizePolicy } from './merge-policy.mjs';
11	import { validatePreconditions, preconditionSignals } from './precondition-policy.mjs';
12	import { applyTaskDefaults } from './task-defaults.mjs';
13	
14	// A declared timeout is always a whole number of seconds, > 0.
15	const isPositiveInt = (n) => Number.isInteger(n) && n > 0;
16	
17	// A code-work command must stay inside its own task directory — no absolute
18	// path and no `..` traversal in the command string — the same containment the
19	// worker-file rule gives agent_instructions (task-code-work DESIGN §2).
20	const escapesTaskDir = (cmd) => /(^|\s)\//.test(cmd) || cmd.includes('..');
21	
22	// Task execution is two similar, consecutive phases — deterministic CODE-WORK,
23	// then AGENTIC WORK — and the field names say so. Neither phase is named for
24	// the other: the code phase is not preparation for the agent, it is the first
25	// of two peers, and a task may declare only it.
26	//
27	// Two renames have reached these fields (2026-08-06 agent_preprocessing →
28	// prework, 2026-08-18 prework → code-work). Every legacy key maps straight to
29	// today's canonical name rather than to its immediate successor, so a declaration
30	// written for the oldest vocabulary normalizes in one pass, and a canonical name
31	// wins where both are present.
32	//
33	// Scaffolding, not a second vocabulary the contract keeps: `legacy-task-fields`
34	// reports a declaration still on an old spelling, and the acceptance ends one
35	// convergence window after that advisory ships (#1642). Not "once nobody declares
36	// them" — nothing here can count that.
37	// @legacy-tolerance advisory:legacy-task-fields retire:#1642
38	export const LEGACY_FIELDS = {
39	  agent_preprocessing: 'code_work',
40	  agent_preprocessing_timeout: 'code_work_timeout',
41	  prework: 'code_work',
42	  prework_timeout: 'code_work_timeout',
43	  after: 'schedule_after',
44	  // 2026-09-03: the secrets a task needs are the CODE-WORK phase's (that is the
45	  // only phase that runs Action-side, where a secret exists), and the name says so.
46	  required_secrets: 'code_work_required_secrets',
47	};
48	
49	// The defaults live in task-defaults.mjs — a module with no imports, so the
50	// dashboard's browser bundle can fill them the way the loader does.
51	export { DEFAULT_PRECONDITIONS, DEFAULT_AUTOMERGE, DEFAULT_AGENT_MODEL } from './task-defaults.mjs';
52	
53	// Return the declaration with canonical field names and the defaults filled in.
54	// Non-objects pass through untouched so validateTaskDeclaration still reports
55	// them. Loaders (discover, resolve-dispatch) normalize once; everything
56	// downstream sees only `code_work` and never an absent defaulted field.
57	export function normalizeTaskDeclaration(decl) {
58	  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) return decl;
59	  const out = { ...decl };
60	  // The editor's schema pointer, when a caller hands over a parsed task.json whole.
61	  delete out.$schema;
62	  for (const [legacy, canonical] of Object.entries(LEGACY_FIELDS)) {
63	    if (out[legacy] !== undefined) {
64	      if (out[canonical] === undefined) out[canonical] = out[legacy];
65	      delete out[legacy];
66	    }
67	  }
68	  // THE ONE DOOR for the retired frequency spellings (DESIGN §17.1). Here rather than in the
69	  // calendar because a frequency is read by more than the calendar — see `normalizeFrequency`.
70	  if (out.frequency !== undefined) out.frequency = normalizeFrequency(out.frequency);
71	  // The retired outcome ceilings become the outcome/policy pair. An explicit
72	  // `automerge` beside a legacy spelling wins: a half-migrated declaration
73	  // keeps the narrower intent it states.
74	  if (LEGACY_OUTCOMES[out.expected_outcome] !== undefined) {
75	    if (out.automerge === undefined) out.automerge = LEGACY_OUTCOMES[out.expected_outcome];
76	    out.expected_outcome = 'pr';
77	  }
78	  return applyTaskDefaults(out);
79	}
80	
81	// The write ceiling a task declares (DESIGN §1, §4). A declared MAXIMUM, not a
82	// promise: `none` may never open a PR; `pr` may open one, and what (if anything)
83	// the run may then MERGE is the separate `automerge` policy — 'nothing',
84	// 'anything', or a list of diff classes merge-policy.mjs evaluates the actual
85	// diff against. "No change" is always legal.
86	export const OUTCOMES = ['none', 'pr'];
87	
88	// The retired one-word ceilings, each carrying the policy it always meant, and
89	// normalizing at the door like the code-work renames above: `open-pr` is a pr task
90	// that merges nothing, `merged-pr` a pr task authorized for anything. Accepted on
91	// the same terms as the renames above — one convergence window past the advisory,
92	// and no longer (#1642).
93	// @legacy-tolerance advisory:legacy-task-fields retire:#1642
94	export const LEGACY_OUTCOMES = { 'open-pr': 'nothing', 'merged-pr': 'anything' };
95	
96	
97	// The retired scope vocabulary. It routed a slot dispatch to one of two labels, and
98	// its last reader went with the slot scheduler (#974): reach is now a property of
99	// which endpoint the hand-off calls (`invocation_endpoint`), so nothing anywhere
100	// asks a task what its scope is.
101	//
102	// The values stay so a declaration still carrying the field VALIDATES rather than
103	// failing — nothing converges a member's task files, so a member cannot be moved
104	// off it by a release; `task-declaration-shape` raises it as an advisory rename
105	// instead, and the field is dropped as each declaration is next edited.
106	// @deprecated Declares nothing. Name an `invocation_endpoint` if the task needed
107	//   reach an ordinary session in its repo does not have.
108	// @legacy-tolerance advisory:task-declaration-shape retire:#1642
109	export const SESSION_SCOPES = ['self', 'fleet'];
110	
111	// What must happen to a task's work item when a recovery path would re-execute it
112	// (tasks-dispatch DESIGN §6). `requeue` is the safe-side default for sweep-shaped
113	// work; `needs-human` is the at-most-once dial a one-shot side effect declares.
114	export const INTERRUPT_POLICIES = ['requeue', 'needs-human'];
115	
116	
117	// The signal-collector vocabulary (DESIGN §3.3). A task collects only the union
118	// of what its due tasks declare. `fleet` is canon-only (consumers cannot declare
119	// it) — that restriction is enforced where signals are collected, not here; the
120	// shape check only asserts a declared name is a real collector.
121	export const SIGNAL_NAMES = [
122	  'commits', 'prs', 'issues', 'branches', 'release',
123	  'localPacks', 'sharedMount', 'conversationLogs', 'stamp', 'fleet', 'request',
124	];
125	
126	// `description` — what the task does, or why it exists, for the person reading the
127	// declaration or a roster of them: free prose, bounded so it stays a summary. It
128	// must not restate what the other fields already say (the cadence, the
129	// conditions, the policy, the files); the writing-tasks skill holds that rule,
130	// which no check can read.
131	export const DESCRIPTION_MAX_WORDS = 50;
132	export const wordCount = (text) => String(text).trim().split(/\s+/).filter(Boolean).length;
133	export function descriptionProblem(description) {
134	  if (typeof description !== 'string') return { what: `"description" is not a string`, fix: 'write one sentence or two saying what the task does or why it exists' };
135	  if (description.trim() === '') return { what: '"description" is empty', fix: 'say what the task does or why it exists, or drop the field' };
136	  const words = wordCount(description);
137	  if (words > DESCRIPTION_MAX_WORDS) return { what: `"description" runs to ${words} words`, fix: `keep it to ${DESCRIPTION_MAX_WORDS} words — a summary, not the README` };
138	  return null;
139	}
140	
141	// Validate one task declaration. Returns an array of `{ what, fix }` problems —
142	// empty means the declaration is well-formed. Pure: no I/O, no imports of the
143	// task itself; the caller supplies the already-loaded default export.
144	export function validateTaskDeclaration(raw, terms = new Map()) {
145	  const decl = normalizeTaskDeclaration(raw);
146	  if (decl === null || typeof decl !== 'object' || Array.isArray(decl)) {
147	    return [{ what: 'task.json is not a declaration object', fix: 'write one JSON object: { "id", "frequency", "preconditions", "expected_outcome", … }' }];
148	  }
149	  const problems = [];
150	  const bad = (what, fix) => problems.push({ what, fix });
151	
152	  if (typeof decl.id !== 'string' || decl.id.trim() === '') {
153	    bad('the task has no string "id"', 'give the task an "id" matching its directory name');
154	  }
155	  // Optional at the door — nothing converges a member's task files — and judged
156	  // only when declared; the shape check asks for one where it is missing.
157	  if (decl.description !== undefined) {
158	    const problem = descriptionProblem(decl.description);
159	    if (problem) bad(problem.what, problem.fix);
160	  }
161	  // ACCEPTED, not FREQUENCIES: a member's own task file may still carry a retired spelling and
162	  // must keep running, since nothing converges a member's task files. Stopping a NEW declaration
163	  // from naming one is the author-time declaration-shape check's job, not this one's — the split
164	  // is deliberate, and `FREQUENCIES` beside `ACCEPTED_FREQUENCIES` in calendar.mjs is where it is
165	  // spelled out.
166	  if (!ACCEPTED_FREQUENCIES.includes(decl.frequency)) {
167	    bad(`"frequency" ${JSON.stringify(decl.frequency)} is not a legal frequency`, `set one of: ${ACCEPTED_FREQUENCIES.join(', ')}`);
168	  }
169	  // `precondition_signals` is retired with the function form it belonged to
170	  // (#1617). The union is DERIVED from the expression's terms, each of which
171	  // names what it reads, so the collector can never disagree with what the gate
172	  // actually consults — a declared list can, and that is the whole reason the
173	  // derived one replaced it.
174	  if (decl.precondition_signals !== undefined) {
175	    bad('"precondition_signals" is retired', 'drop it — the signal union is derived from the conditions, each of which names what it reads');
176	  }
177	  if (!MODEL_FAMILIES.includes(decl.agent_model)) {
178	    bad(`"agent_model" ${JSON.stringify(decl.agent_model)} is not a legal model family`, `set one of: ${MODEL_FAMILIES.join(', ')}`);
179	  }
180	  if (!OUTCOMES.includes(decl.expected_outcome)) {
181	    bad(`"expected_outcome" ${JSON.stringify(decl.expected_outcome)} is not a legal outcome ceiling`, `set one of: ${OUTCOMES.join(', ')}`);
182	  }
183	  // automerge — defaulted to `nothing` beside `pr` at the door (the legacy
184	  // ceilings arrive here already carrying theirs), and validated as a policy
185	  // SHAPE only: whether every named
186	  // rule resolves is the policy engine's question, answered where the diff is
187	  // judged, and it fails closed there — never at author time, where the rule set
188	  // depends on which packs are active.
189	  if (decl.expected_outcome === 'pr') {
190	    if (decl.automerge === undefined) {
191	      bad('a "pr" task declares no "automerge"', 'say what may land unreviewed: "nothing", "anything", or a list of diff classes, e.g. ["comment-only-changes", "readme-changes"]');
192	    } else {
193	      const policy = normalizePolicy(decl.automerge);
194	      if (policy.kind === 'invalid') {
195	        bad(`"automerge" is not a legal policy: ${policy.reason}`, 'set "nothing", "anything", or a list of rule names, each optionally reject:-prefixed');
196	      }
197	    }
198	  } else if (decl.automerge !== undefined) {
199	    bad('a "none" task declares "automerge"', 'drop it — a task that opens no pull request has nothing to merge; or set expected_outcome: "pr"');
200	  }
201	  // agent_instructions — REQUIRED for an agentic task (agent_model !== 'none'):
202	  // that's the worker file the agent reads, and it has no default. A `none` task
203	  // runs no agent, so the field is not applicable and is neither required nor
204	  // validated when present.
205	  if (decl.agent_model !== 'none' && (typeof decl.agent_instructions !== 'string' || decl.agent_instructions.trim() === '')) {
206	    bad('an agentic task (agent_model !== "none") declares no string "agent_instructions"', 'point "agent_instructions" at the worker file beside task.json (e.g. "task.md")');
207	  }
208	  // ONE MECHANISM (#1617). `preconditions` — a list of named conditions, all of
209	  // which must hold — is the only gate a task declares. The `precondition`
210	  // function it replaced is retired rather than tolerated: two forms meant every
211	  // reader, every check and the evaluator itself had to ask which one was the
212	  // gate, and a task-local term does everything the function did while staying
213	  // pure over its inputs and testable at a chosen instant.
214	  //
215	  // A term answers three ways, not two: holds, does not hold, and `{ error }` —
216	  // it COULD NOT ANSWER. The third is a run failure rather than a verdict (F27):
217	  // a decline is a decision about the world, and one taken on an API that would
218	  // not answer is a guess whose write-backs cannot land.
219	  if (decl.precondition !== undefined) {
220	    bad('the task declares a "precondition" function, which is retired', 'move the gate into "preconditions" — a built-in condition, or a term this task\'s preconditions.mjs exports');
221	  }
222	  if (decl.preconditions === undefined) {
223	    bad('the task declares no "preconditions"', 'add "preconditions": a list of named conditions, all of which must hold (e.g. ["substantive-change"], or ["none"] for a task the calendar triggers)');
224	  } else {
225	    for (const problem of validatePreconditions(decl.preconditions, terms)) bad(problem.what, problem.fix);
226	  }
227	
228	  /**
229	   * model_from_request — OPTIONAL, and reserved to the engine's own built-in task.
230	   * A task that declares it runs at the model the ITEM names (`Model:`, written by
231	   * the scheduler run from a write-gated label), falling back to `agent_model` when the item
232	   * names none. It is the only field that lets anything on an item define behaviour,
233	   * so it is fenced rather than waved through (DESIGN §16.7): the shape check accepts
234	   * only `true`, and discovery gives pack tasks no way to be the built-in one.
235	   */
236	  if (decl.model_from_request !== undefined && decl.model_from_request !== true) {
237	    bad(`"model_from_request" ${JSON.stringify(decl.model_from_request)} is not \`true\``,
238	      'drop the field — only the engine\'s built-in request task reads a model off its item, and every other task names its own agent_model');
239	  }
240	
241	  /**
242	   * session_scope — OPTIONAL, and READ BY NOTHING. Kept validated rather than
243	   * rejected outright so a lingering declaration still loads: nothing carries a
244	   * task-file change across the fleet, so a member cannot be migrated off the field
245	   * by a release, and rejecting it would stop that member's task running over a word
246	   * that no longer does anything.
247	   * @deprecated Declares nothing since #974. Drop it; if the task needed reach an
248	   *   ordinary session in its repo does not have, name an `invocation_endpoint`.
249	   */
250	  if (decl.session_scope !== undefined && !SESSION_SCOPES.includes(decl.session_scope)) {
251	    bad(`"session_scope" ${JSON.stringify(decl.session_scope)} is not a legal session scope`, `drop it — the field is read by nothing; name an "invocation_endpoint" if the task needs wider reach`);
252	  }
253	
254	  // Code-work (task-code-work DESIGN §2) — OPTIONAL. The deterministic first phase
255	  // of task execution, a command the scheduler runs as a subprocess. When present
256	  // it must be a non-empty, task-local command AND carry a positive-integer
257	  // code_work_timeout — the hard kill that bounds the subprocess.
258	  if (decl.code_work !== undefined) {
259	    if (typeof decl.code_work !== 'string' || decl.code_work.trim() === '') {
260	      bad('"code_work" is present but not a non-empty string', 'set it to a command whose executable is a script beside task.json, e.g. "node prepare.mjs"');
261	    } else if (escapesTaskDir(decl.code_work)) {
262	      bad('"code_work" reaches outside the task directory (absolute path or "..")', 'reference a sibling script only, e.g. "node prepare.mjs"');
263	    }
264	    if (!isPositiveInt(decl.code_work_timeout)) {
265	      bad('"code_work" is set but "code_work_timeout" is not a positive integer', 'add "code_work_timeout": the seconds after which the subprocess is killed and the task fails');
266	    } else if (decl.code_work_timeout * 1000 >= EXECUTING_LEASH_MS) {
267	      // F17: a code-work legally allowed to outlive the executing leash is reclaimed
268	      // WHILE ALIVE, and the failure is not one duplicate run but a livelock —
269	      // every tenure reclaimed before it can finish, code-work re-executing each
270	      // cycle, the occurrence never converging. The leash is the engine's, so the
271	      // comparison is made where a declaration is judged.
272	      bad(`"code_work_timeout" (${decl.code_work_timeout}s) reaches the executor's ${EXECUTING_LEASH_MS / 60e3}-minute claim leash`,
273	        `bound code_work under ${EXECUTING_LEASH_MS / 60e3} minutes — a code_work that can outlive the leash is reclaimed while still running, and the item livelocks`);
274	    }
275	  }
276	
277	  // --- the work-item queue's three optional declarations (tasks-dispatch DESIGN) ---
278	
279	  // `schedule_after` — ordering, declared (DESIGN §9). A list of `<pack>/<task>` ids this
280	  // task yields to WHILE THEY ARE LIVE THIS CYCLE. It compiles to the executor's
281	  // pick-time yield, never to a `Blocked-by` edge: a standing item that rolls
282	  // never closes, so blocked-by would starve every dependent of a quiet upstream
283	  // forever. The engine never learns what any named task does — it reads item
284	  // states, generically.
285	  if (decl.schedule_after !== undefined
286	      && !(Array.isArray(decl.schedule_after)
287	        && decl.schedule_after.every((s) => typeof s === 'string' && /^[^/\s]+\/[^/\s]+$/.test(s)))) {
288	    bad('"schedule_after" is not an array of "<pack>/<task>" ids', 'e.g. "schedule_after": ["claudinite-lifecycle/update"] — this task is not scheduled onto an executor while those are live this cycle');
289	  }
290	
291	  // `on_interrupt` — the ack-early/ack-late dial (DESIGN §6). Most of this fleet's
292	  // tasks are sweep-shaped and converge safely on a re-run, so the default is
293	  // `requeue`. A genuinely one-shot side effect (a store submission, an external
294	  // notification) declares `needs-human`, and every recovery path that would
295	  // re-execute it — the leash reclaim, the hand-off retry — converges to triage
296	  // instead: at-most-once plus a human.
297	  if (decl.on_interrupt !== undefined && !INTERRUPT_POLICIES.includes(decl.on_interrupt)) {
298	    bad(`"on_interrupt" ${JSON.stringify(decl.on_interrupt)} is not a legal policy`, `set one of: ${INTERRUPT_POLICIES.join(', ')} (default "requeue")`);
299	  }
300	
301	  // `invocation_endpoint` — a NAME, never a URL (DESIGN §12). The repo's config
302	  // maps the name to the URL and to the name of the Actions secret holding its
303	  // token, so no vendored pack file carries deployment detail or anything adjacent
304	  // to a credential. This is also what replaces session_scope: reach is a property
305	  // of which endpoint a task names.
306	  if (decl.invocation_endpoint !== undefined
307	      && !(typeof decl.invocation_endpoint === 'string' && /^[a-z0-9]+(-[a-z0-9]+)*$/.test(decl.invocation_endpoint))) {
308	    bad('"invocation_endpoint" is not a kebab-case endpoint name', 'name a key from the repo\'s taskScheduler.agenticTaskInvocationEndpoints map, e.g. "fleet" — never a URL');
309	  }
310	
311	  // The repo Actions secrets this task's code work needs configured (DESIGN §9). Purely
312	  // DECLARATIVE — like a pack's adoption `questions`, its job is to drive the ask
313	  // (adoption interactively, the scheduler by owner issue), not to gate anything
314	  // here. So the only shape asserted is "a list of names"; whether the repo has
315	  // actually configured them is a fact about the repo, answered where the secrets
316	  // bundle is readable, never at author time.
317	  if (decl.code_work_required_secrets !== undefined
318	      && !(Array.isArray(decl.code_work_required_secrets) && decl.code_work_required_secrets.every((s) => typeof s === 'string' && s.trim() !== ''))) {
319	    bad('"code_work_required_secrets" is not an array of secret names', 'list the repo Actions secret names this task needs, e.g. ["SOME_API_KEY"]');
320	  }
321	
322	  // The one exception to "whether the repo has them is not our business": GitHub
323	  // reserves the `GITHUB_` prefix, answering "Secret names must not start with
324	  // GITHUB_" on the secret form. Such a name cannot be configured by anyone, so the
325	  // task parks forever on a secret its owner is refused — and only the declaration
326	  // can catch it, since the park reads as ordinary missing configuration.
327	  for (const name of (Array.isArray(decl.code_work_required_secrets) ? decl.code_work_required_secrets : [])) {
328	    if (typeof name === 'string' && name.toUpperCase().startsWith('GITHUB_')) {
329	      bad(`required secret "${name}" cannot be created — GitHub reserves the GITHUB_ prefix`,
330	        'rename it without that prefix, e.g. one carrying the pack\'s own name');
331	    }
332	    // The other namespace a secret cannot borrow. `CLAUDINITE_*` in a task file is the
333	    // code-work contract, and `task-code-work-env` reads every name outside that
334	    // contract as a variable nobody sets — which a delivered secret is not, so the
335	    // finding would be unfixable without renaming the secret anyway.
336	    if (typeof name === 'string' && name.toUpperCase().startsWith('CLAUDINITE_')) {
337	      bad(`required secret "${name}" sits in the code-work namespace, which its task's own code may not read`,
338	        'rename it outside CLAUDINITE_* — that prefix belongs to the variables code_work is handed');
339	    }
340	  }
341	
342	  // Execution bound (task-code-work DESIGN §2, §6) — an agentic task MUST
343	  // declare a positive-integer agent_execution_timeout: there is no default,
344	  // because a running agent always has a bound. Enforcement is best-effort (the
345	  // executor surfaces the value to the subagent). A `none` task runs no agent,
346	  // so it needs none.
347	  if (MODEL_FAMILIES.includes(decl.agent_model) && decl.agent_model !== 'none' && !isPositiveInt(decl.agent_execution_timeout)) {
348	    bad('an agentic task (agent_model !== "none") declares no positive-integer "agent_execution_timeout"', 'add "agent_execution_timeout": the seconds bounding the agentic run — generous; extreme protection, not a scheduling knob');
349	  }
350	
351	  // An agentless task (agent_model: none) runs no agent, so its ONLY work is
352	  // code-work — a `none` task with no code-work does nothing (DESIGN §4, retiring
353	  // the in-process inline path). Require the command.
354	  if (decl.agent_model === 'none' && decl.code_work === undefined) {
355	    bad('an agentless task (agent_model: "none") declares no "code_work"', 'add "code_work" (a none task does its work in that subprocess) — or give the task an agent_model');
356	  }
357	
358	  return problems;
359	}
360	
361	// The signals to collect for one task, derived from the terms its conditions
362	// name. There is nothing to reconcile: a declared list could disagree with what
363	// the gate actually consults, and the derived union cannot.
364	export function taskSignalNames(decl, terms = new Map()) {
365	  return preconditionSignals(decl?.preconditions ?? [], terms);
366	}
