183	    ops.push({ kind: 'addLabel', issue: request, name: IN_REVIEW_LABEL });
184	  }
185	  return ops;
186	}
187	
188	// THE SESSION EXECUTOR'S SCRIPT. Same ops, addressed to the GitHub tools a session
189	// does have. Two differences forced by that surface, both handled here rather than
190	// left to the session to work out:
191	//
192	//  - THERE IS NO GRANULAR LABEL WRITE. `issue_write` replaces the whole set, so the
193	//    granular removes and adds are folded into the FINAL set here, computed from the
194	//    labels this item was read with. Everything not a status label is carried through.
195	//  - THE RECORD IS PRINTED BY THE SESSION, which is where it has to be anyway: the
196	//    usage fold reads the census out of the session transcript.
197	export function sessionScript(item, plan, repo) {
198	  const [owner, name] = String(repo).split('/');
199	  const lines = [];
200	  let n = 0;
201	  const step = (s) => { n += 1; lines.push(`${n}. ${s}`); };
202	
203	  // The item's own label set can be computed exactly, because the item was read
204	  // with its labels. Any OTHER issue's cannot — so that one is emitted as a
205	  // read-modify-write naming only the change, and never as a computed set, which
206	  // would silently drop every label this process never saw.
207	  const own = new Set(labelNames(item));
208	  const foreign = [];
209	  // The body write folds into the item's own `issue_write`, which is one call
210	  // either way. A park never closes, so the step it folds into is the trailing
211	  // label write below.
212	  let newBody = null;
213	
214	  for (const op of convergeOps(item, plan)) {
215	    if (op.kind === 'comment') {
216	      step(`\`add_issue_comment\` — owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.issue}\`, body exactly:\n\n<<<BODY\n${op.body}\n>>>END\n`);
217	    } else if (op.kind === 'record') {
218	      step(`Output this line, on its own, in your reply. Nothing else emits it, and the usage census is read from your transcript:\n\n    ${op.line}\n`);
219	    } else if (op.kind === 'removeLabel' || op.kind === 'addLabel') {
220	      if (op.issue === item.number) {
221	        if (op.kind === 'removeLabel') own.delete(op.name); else own.add(op.name);
222	      } else {
223	        foreign.push(op);
224	      }
225	    } else if (op.kind === 'setBody' && op.issue === item.number) {
226	      newBody = op.body;
227	    } else if (op.kind === 'close') {
228	      step(`\`issue_write\` — method \`update\`, owner \`${owner}\`, repo \`${name}\`, issue_number \`${op.issue}\`,`
229	        + ` labels \`${JSON.stringify([...own])}\`, state \`closed\`, state_reason \`${op.stateReason}\``);
230	      own.clear();
231	    }
232	  }
233	  // A park never closed, so its label write is still owed.
234	  if (own.size) {
235	    step(`\`issue_write\` — method \`update\`, owner \`${owner}\`, repo \`${name}\`, issue_number \`${item.number}\`,`
236	      + ` labels \`${JSON.stringify([...own])}\``
237	      + (newBody === null ? '' : `, body exactly:\n\n<<<BODY\n${newBody}\n>>>END\n`));
238	  }
239	  for (const op of foreign) {
240	    step(`On #${op.issue}: ${op.kind === 'addLabel' ? 'ADD' : 'REMOVE'} the label \`${op.name}\`.`
241	      + ` Read that issue's current labels first and write them back with only this one change —`
242	      + ` \`issue_write\` replaces the whole set, and this process never saw the rest.`);
243	  }
244	  return lines.join('\n');
245	}
